/**
 * @method
 * @name scwin.findPosY
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.findPosY = function (obj) {
    /* sdd-asis-lifecycle:begin findPosY — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let curtop = 0;
    if (obj.offsetParent) {
        while (obj.offsetParent) {
            curtop += obj.offsetTop;
            obj = obj.offsetParent;
        }
    } else {
        if (obj.y) {
            curtop += obj.y;
        }
    }
    return curtop;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param mode
 * @returns
 * @hidden N
*/
scwin.submit = async function (mode) {
    /* sdd-asis-lifecycle:begin submit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const f = (document.form || { elements: [] });
    f.action = "/PersonInfo.do";
    $c.util.getComponent('dma_submitReq').set('method', "itemSearchList");
    $c.util.getComponent('dma_submitReq').set('SCREN_PROCES_TP_CD', "01");
    if ((String($c.util.getComponent('ipt_check1').getValue() || "") !== "")) {
        $c.util.getComponent("dma_submitReq").set("jrKind1", "00");
    }
    if ((String($c.util.getComponent('ipt_check2').getValue() || "") !== "")) {
        $c.util.getComponent("dma_submitReq").set("jrKind2", encodeURI("대표이사"));
    }
    if ((String($c.util.getComponent('ipt_check3').getValue() || "") !== "")) {
        $c.util.getComponent("dma_submitReq").set("jrKind3", "02");
    }
    if (mode == null) {
        $c.util.getComponent('dma_submitReq').set('newsScrollY', "");
        $c.util.getComponent('dma_submitReq').set('pageNum', "1");
    }
    $c.util.getComponent("ipt_comName").setValue(encodeURI($c.util.getComponent('ipt_comName').getValue()));
    $c.util.getComponent("dma_submitReq").set("beforeName", encodeURI($c.util.getComponent("dma_submitReq").get("beforeName")));
    if ($c.num.isNumber($c.util.getComponent('ipt_comCode').getValue()) && $c.util.getComponent('ipt_comCode').getValue().length == 6) {
        $c.util.getComponent("ipt_comCode").setValue("A" + $c.util.getComponent('ipt_comCode').getValue());
    }
    if ((document.form || { elements: [] }).regcncl[1].checked) {
        /* 수동 전환 필요: regcncl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
    } else {
        /* 수동 전환 필요: regcncl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
    }
    await scwin.tx_submit();

    /* sdd-asis-lifecycle:end */
};


