/**
 * @method
 * @name scwin.searchCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param searchValue
 * @returns
 * @hidden N
*/
scwin.searchCode = function (searchValue) {
    /* sdd-asis-lifecycle:begin searchCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let iCount = 0;
    arrReset();
    for (let j = 0; j < jr.length; j++) {
        if (searchValue === jr[j].jcode.substring(0, searchValue.length)) {
            if (jr[j].jname.indexOf("변경전사명") < 1) {
                if (regcncl === "1") {
                    arrCode[iCount] = jr[j].jcode;
                    arrName[iCount] = jr[j].jname;
                    iCount++;
                } else {
                    if (jr[j].jname.indexOf("폐지") < 1) {
                        arrCode[iCount] = jr[j].jcode;
                        arrName[iCount] = jr[j].jname;
                        iCount++;
                    }
                }
            }
        }
    }
    setSelectBox();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.pageNav
 * @author Inswave
 * @date 2026. 09. 29
 * @param funcName pageNum pageSize total
 * @returns
 * @hidden N
*/
scwin.pageNav = function (funcName, pageNum, pageSize, total) {
    /* sdd-asis-lifecycle:begin pageNav — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (total < 1) {
        return "";
    }
    let ret = "";
    const PAGEBLOCK = 10;
    const totalPages = Math.floor((total - 1) / pageSize) + 1;
    let firstPage = Math.floor((pageNum - 1) / PAGEBLOCK) * PAGEBLOCK + 1;
    if (firstPage <= 0) {
        firstPage = 1;
    }
    let lastPage = firstPage - 1 + PAGEBLOCK;
    if (lastPage > totalPages) {
        lastPage = totalPages;
    }
    if (firstPage > PAGEBLOCK) {
        ret += navAnchor(funcName, 1, "<<처음") + "&nbsp;\n";
        ret += navAnchor(funcName, (firstPage - 1), "<이전") + "&nbsp;\n";
    }
    for (i = firstPage; i <= lastPage; i++) {
        if (pageNum === i) {
            ret += "<a class='active' onclick='return false;' href='#page_link_" + 1 + "'>" + i + "</a>&nbsp;\n";
        } else {
            ret += navAnchor(funcName, i, i) + "&nbsp;\n";
        }
    }
    if (lastPage < totalPages) {
        ret += navAnchor(funcName, (lastPage + 1), "다음>") + "&nbsp;\n";
        ret += "&nbsp;" + navAnchor(funcName, totalPages, "끝>>") + "\n";
    }
    return ret;
    /* sdd-asis-lifecycle:end */
};
